export const LESSONS: Record<string, Lesson> = {
  "systems.iceberg_model": { kind: "tool", href: "/learn/systems.iceberg_model", title: "冰山模型：開始前 5 分鐘", html: "  <div class=\"crumbs\"><a href=\"/methods\">工具</a> › <a href=\"/methods/systems.iceberg_model\">冰山模型</a> › 5 分鐘課</div>\n\n  <div class=\"top\">\n    <div>\n      <h1>冰山模型：開始前 5 分鐘</h1>\n      <div class=\"sub\">想直接做，按下面的「開始填我的案例」；想先學，照分頁一頁一頁看，每頁不到兩分鐘。</div>\n    </div>\n  </div>\n  <div class=\"status\"><span class=\"pill ok\">工具齊備 M1–M10 ✓</span><span>課程來源 3 筆 <cite>[1]</cite><cite>[2]</cite><cite>[3]</cite></span><span>約 5 分鐘</span><span>學完你會：分清四層、把一件事填成四段、看懂結果頁、知道什麼時候不該用</span><span>教材版在「教材版」分頁（給老師／帶領者）</span></div>\n\n  <div class=\"card cta\" id=\"start\">\n    <h2>開始：填你自己的案例<small>準備 30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>這張卡一直在最上面；下面的分頁是課程，看完或看到一半都能回來按。<b>你要做的</b>按「開始填我的案例」；還不確定，先用示範案例試一次，或按第三顆讓系統幫你挑。</div>\n    <div class=\"btns\">\n      <a class=\"btn primary big\" href=\"/methods/systems.iceberg_model/run\">開始填我的案例 →<small>四個空格子，每格旁邊有提示和例子；按「執行分析」才開始</small></a>\n      <a class=\"btn\" href=\"/methods/systems.iceberg_model/run#demo\">用示範案例試一次<small><span class=\"ex\" data-set=\"edd\">主動分享 6 → 2 人那個例子，已填好，按執行就看結果</span><span class=\"ex\" data-set=\"partner\" hidden>畫廊延後付款那個例子，已填好，按執行就看結果</span><span class=\"ex\" data-set=\"decision\" hidden>加開平日班那個例子，已填好，按執行就看結果</span><span class=\"ex\" data-set=\"ecom\" hidden>退貨率 12% 那個例子，已填好，按執行就看結果</span><span class=\"ex\" data-set=\"daily\" hidden>週日晚上吵架那個例子，已填好，按執行就看結果</span></small></a>\n      <a class=\"btn ghost\" href=\"/#ask\">這工具適合我的問題嗎？<small>描述你的問題，系統幫你挑，最多三個建議</small></a>\n    </div>\n    <p class=\"sub mt10 mb0\">手邊有這些會填得比較快，沒有也可以先填、之後補：</p>\n    <ul class=\"check\">\n      <li>一件具體的事（時間、數字）</li>\n      <li>過去半年左右的紀錄或數字（同一件事發生幾次）</li>\n      <li>相關的流程、規則、人力安排</li>\n      <li>你們開會時常常出現的那句話（信念通常藏在口頭禪裡）</li>\n    </ul>\n    <p class=\"sub mb0\">這堂課之後不會再自動出現；想再看，工具頁右上角「怎麼用？」隨時能打開，會另開一個分頁，填到一半的格子不會不見。</p>\n  </div>\n\n    <div class=\"chips\" role=\"tablist\" aria-label=\"例子領域\">\n      <span class=\"sub\">例子領域：</span>\n      <button class=\"chip on\" role=\"tab\" aria-selected=\"true\" data-set=\"edd\" id=\"chip-edd\">藝術反思／EdD 研究（你的預設）</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"partner\" id=\"chip-partner\">合作對象</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"decision\" id=\"chip-decision\">一個決策</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"ecom\" id=\"chip-ecom\">電商後台</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"daily\" id=\"chip-daily\">日常</button>\n    </div>\n  <div class=\"tabs\" role=\"tablist\" aria-label=\"課程內容\">\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-learn\" aria-controls=\"panel-learn\" aria-selected=\"true\" tabindex=\"0\">認識<small>1.5 分</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-example\" aria-controls=\"panel-example\" aria-selected=\"false\" tabindex=\"-1\">看例子<small>1 分</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-fill\" aria-controls=\"panel-fill\" aria-selected=\"false\" tabindex=\"-1\">怎麼填<small>1.5 分</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-read\" aria-controls=\"panel-read\" aria-selected=\"false\" tabindex=\"-1\">看懂結果<small>1 分</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-teach\" aria-controls=\"panel-teach\" aria-selected=\"false\" tabindex=\"-1\">教材版</button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-sources\" aria-controls=\"panel-sources\" aria-selected=\"false\" tabindex=\"-1\">來源</button>\n  </div>\n\n  <section class=\"tabpanel\" id=\"panel-learn\" role=\"tabpanel\" aria-labelledby=\"tab-learn\">\n  <div class=\"card\">\n    <h2>這是什麼<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先讀三段文字，再看下面那張四層冰山：左邊是每層要問的問題，右邊是在那一層出手會得到什麼；結果頁用的是同一張圖，只是填上你的資料。<b>你要做的</b>不用做；只看「什麼時候不用」那一句：你的問題如果是一次性的意外，這個工具不適合，去最上面「開始」卡按第三顆按鈕。</div>\n    <div class=\"grid2\">\n      <div>\n        <p class=\"lead\">冰山浮在水面上的只有一小角。<b>問題也是</b>：你看到的是「發生了什麼事」，真正決定它一再發生的原因藏在水面下。</p>\n        <p>冰山模型是一種<dfn title=\"Systems Thinking：把問題當成一個互相牽動的系統來看，而不是單一事件\">系統思考</dfn>的工具：把一件事往下挖四層，從「發生什麼」挖到「大家心裡怎麼想」。挖得越深，能改的東西越根本 <cite>[2]</cite>。</p>\n        <p class=\"sub\">什麼時候用：同一種問題一再出現、換人換工具都沒用、大家在互相怪罪的時候。什麼時候不用：一次性的意外、單純缺資料的問題 <cite>[1]</cite>。</p>\n      </div>\n      <svg viewBox=\"0 0 1070 575\" role=\"img\" aria-label=\"冰山模型四層圖\">\n        <defs>\n          <linearGradient id=\"ice\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0\" stop-color=\"#fbe3d6\"/><stop offset=\"0.2\" stop-color=\"#cfe3f3\"/><stop offset=\"0.5\" stop-color=\"#5a93c4\"/><stop offset=\"0.75\" stop-color=\"#245b8a\"/><stop offset=\"1\" stop-color=\"#0b2a4a\"/>\n          </linearGradient>\n          <clipPath id=\"berg\"><path d=\"M550,150 L585,40 L620,85 L645,55 L690,150 L810,290 L780,420 L690,540 L560,540 L460,420 L420,290 Z\"/></clipPath>\n        </defs>\n        <rect x=\"0\" y=\"150\" width=\"1070\" height=\"425\" class=\"water\" opacity=\"0.55\"/>\n        <path d=\"M0,150 q20,-8 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0\" fill=\"none\" stroke=\"#7aa7cc\" stroke-width=\"2.5\"/>\n        <line x1=\"30\" y1=\"290\" x2=\"1050\" y2=\"290\" stroke=\"#7aa7cc\" stroke-dasharray=\"5 5\"/>\n        <line x1=\"30\" y1=\"420\" x2=\"1050\" y2=\"420\" stroke=\"#7aa7cc\" stroke-dasharray=\"5 5\"/>\n        <path d=\"M550,150 L585,40 L620,85 L645,55 L690,150 L810,290 L780,420 L690,540 L560,540 L460,420 L420,290 Z\" fill=\"url(#ice)\" stroke=\"#1f3b5c\" stroke-width=\"2\"/>\n        <g clip-path=\"url(#berg)\">\n          <line x1=\"400\" y1=\"290\" x2=\"840\" y2=\"290\" stroke=\"#fff\" stroke-dasharray=\"4 4\" opacity=\".7\"/>\n          <line x1=\"400\" y1=\"420\" x2=\"840\" y2=\"420\" stroke=\"#fff\" stroke-dasharray=\"4 4\" opacity=\".7\"/>\n        </g>\n        <g font-weight=\"700\" text-anchor=\"middle\">\n          <text class=\"tip\" x=\"618\" y=\"128\" font-size=\"17\">事件 Events</text>\n          <text x=\"618\" y=\"230\" font-size=\"17\" class=\"w\">模式 Patterns</text>\n          <text x=\"618\" y=\"362\" font-size=\"17\" class=\"w\">結構 Structures</text>\n          <text x=\"618\" y=\"490\" font-size=\"17\" class=\"w\">心智模型 Mental Models</text>\n        </g>\n        <text x=\"30\" y=\"62\" font-size=\"15\" font-weight=\"700\">看得見：發生了什麼</text>\n        <text x=\"30\" y=\"172\" font-size=\"15\" font-weight=\"700\">看不見：</text>\n        <g font-size=\"14.5\">\n          <text x=\"30\" y=\"96\" font-weight=\"700\">① 事件｜發生了什麼？</text>\n          <text x=\"30\" y=\"118\" font-size=\"13\" class=\"m\">一件具體的事：時間、人數、數字</text>\n          <text x=\"30\" y=\"212\" font-weight=\"700\">② 模式｜以前發生過嗎？多常？跟什麼一起出現？</text>\n          <text x=\"30\" y=\"234\" font-size=\"13\" class=\"m\">一直重複的模式（是線索，不是原因）</text>\n          <text x=\"30\" y=\"346\" font-weight=\"700\">③ 結構｜什麼流程、規則、資源安排在製造它？</text>\n          <text x=\"30\" y=\"368\" font-size=\"13\" class=\"m\">製造模式的制度（寫制度，不寫某個人）</text>\n          <text x=\"30\" y=\"472\" font-weight=\"700\">④ 心智模型｜哪個沒說出口的假設撐住這些結構？</text>\n          <text x=\"30\" y=\"494\" font-size=\"13\" class=\"m\">撐住制度的信念（常藏在口頭禪裡；自己的也要寫）</text>\n        </g>\n        <g font-size=\"14.5\">\n          <text x=\"830\" y=\"96\" font-weight=\"700\">回應 React</text>\n          <text x=\"830\" y=\"118\" font-size=\"13\" class=\"m\">當次有效，下次一樣</text>\n          <text x=\"830\" y=\"212\" font-weight=\"700\">預測 Anticipate</text>\n          <text x=\"830\" y=\"234\" font-size=\"13\" class=\"m\">提早看到，不會阻止</text>\n          <text x=\"830\" y=\"346\" font-weight=\"700\">設計 Design</text>\n          <text x=\"830\" y=\"368\" font-size=\"13\" class=\"m\">改流程、改規則 → 持久</text>\n          <text x=\"830\" y=\"472\" font-weight=\"700\">轉化 Transform</text>\n          <text x=\"830\" y=\"494\" font-size=\"13\" class=\"m\">改信念、改角色 → 最根本</text>\n          <text x=\"830\" y=\"560\" font-size=\"12\" class=\"a\">↓ 越往下：越難改，效果越大越持久</text>\n        </g>\n      </svg>\n    </div>\n    <div class=\"grid2c\">\n      <div class=\"can\"><b>這工具能回答</b>問題為什麼一再發生（哪一層在推）、先在哪一層出手最值得、接下來該做什麼。</div>\n      <div class=\"cant\"><b>這工具不能回答</b>誰對誰錯；你填的內容以外的事實（除非接上資料蒐集）；數字目標由你定，AI 不替你定。</div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>四層，各配一個你領域的例子<small>1 分鐘</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先在分頁上面按你的領域，再從上往下看四層各一個例子；每層的「問」是你之後要回答的問題 <cite>[3]</cite>。<b>你要做的</b>按一個領域（每個分頁的例子都會跟著換）；把你自己的問題在心裡套進四層試一次。</div>\n    <div class=\"grid2\" id=\"examples\">\n      <div class=\"exlayer l1\"><b>① 事件 Events（看得見）</b><div class=\"q\">問：發生了什麼？</div>\n        <div class=\"ex\" data-set=\"edd\">例：第 6 次 session，8 人只有 2 人主動說自己的作品；第 1 次是 6 人。</div>\n        <div class=\"ex\" data-set=\"partner\" hidden>例：合作的畫廊這次又延後付款。</div>\n        <div class=\"ex\" data-set=\"decision\" hidden>例：這個月又有 5 位家長問能不能加開平日班。</div>\n        <div class=\"ex\" data-set=\"ecom\" hidden>例：這個月退貨率 12%，上個月 5%。</div>\n        <div class=\"ex\" data-set=\"daily\" hidden>例：這週又為了家事吵架。</div></div>\n      <div class=\"exlayer l2\"><b>② 模式 Patterns</b><div class=\"q\">問：以前發生過嗎？多常？什麼時候特別容易發生？</div>\n        <div class=\"ex\" data-set=\"edd\">例：三期都從第 4 次開始掉；帶領者先解讀作品的那幾次掉得最多；線上場更低。</div>\n        <div class=\"ex\" data-set=\"partner\" hidden>例：近一年每次展覽結束都延 30 到 60 天才付。</div>\n        <div class=\"ex\" data-set=\"decision\" hidden>例：每年暑假前詢問暴增，開學後又回落。</div>\n        <div class=\"ex\" data-set=\"ecom\" hidden>例：每次上新品後兩週退貨都衝高；尺寸類商品特別多；促銷檔期更嚴重。</div>\n        <div class=\"ex\" data-set=\"daily\" hidden>例：每次都在週日晚上。</div></div>\n      <div class=\"exlayer l3\"><b>③ 結構 Structures</b><div class=\"q\">問：是什麼流程、規則、資源安排讓它一直發生？</div>\n        <div class=\"ex\" data-set=\"edd\">例：帶領者先講作品的意義再請人回應，說明佔 35 分；紀錄表只問「達到洞察？」。</div>\n        <div class=\"ex\" data-set=\"partner\" hidden>例：合約沒寫付款期限；對方會計每季才結一次帳。</div>\n        <div class=\"ex\" data-set=\"decision\" hidden>例：現有教室只有週末滿，平日閒置；老師都是兼職，平日排不出人。</div>\n        <div class=\"ex\" data-set=\"ecom\" hidden>例：商品頁的尺寸表直接用供應商給的、沒人核對；退貨流程只有「同意／不同意」，不問原因。</div>\n        <div class=\"ex\" data-set=\"daily\" hidden>例：沒有分工表，誰看到誰做。</div></div>\n      <div class=\"exlayer l4\"><b>④ 心智模型 Mental Models（最深）</b><div class=\"q\">問：大家心裡哪個沒說出口的假設，撐住了這些結構？</div>\n        <div class=\"ex\" data-set=\"edd\">例：「參與者需要專家幫他們看見意義。」</div>\n        <div class=\"ex\" data-set=\"partner\" hidden>例：「小工作室不好意思催款。」</div>\n        <div class=\"ex\" data-set=\"decision\" hidden>例：「擴大就是成長。」</div>\n        <div class=\"ex\" data-set=\"ecom\" hidden>例：「退貨是客人的問題，不是我們的問題。」</div>\n        <div class=\"ex\" data-set=\"daily\" hidden>例：「這種小事不用講。」</div></div>\n    </div>\n    <p class=\"sub mt10 mb0\">記法：事件是「一次」，模式是「一再」，結構是「為什麼一再」，心智模型是「為什麼沒人改」。例子跟著你進來的那條線走；不會拿你真實填過的案例當教材。</p>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"example\">下一個分頁：看例子 →</button><a class=\"btn primary\" href=\"/methods/systems.iceberg_model/run\">開始填我的案例 →</a></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-example\" role=\"tabpanel\" aria-labelledby=\"tab-example\" hidden>\n  <div class=\"card\">\n    <h2>看一個做完的例子<small>1 分鐘</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>左到右：這一層填了什麼、只看這一層會做什麼；越往下的解法越根本。<b>你要做的</b>不用做；想看做完的完整結果按下面的按鈕。</div>\n    <div id=\"worked\">\n    <div class=\"ex\" data-set=\"edd\">\n      <p class=\"lead\">團體反思：第 6 次 session，8 位參與者只有 2 位主動說自己的作品。</p>\n      <table>\n        <tr><th>層</th><th>填進去的內容</th><th>只看這一層會做什麼</th></tr>\n        <tr><td>事件</td><td>8 人只有 2 人主動分享；第 1 次是 6 人</td><td>開場多鼓勵、點名（下次一樣）</td></tr>\n        <tr><td>模式</td><td>三期都從第 4 次開始掉；帶領者先解讀作品的場次最低</td><td>每次記人數與說明分鐘、提早看到</td></tr>\n        <tr><td>結構</td><td>帶領者先講作品的意義再請人回應；說明佔 35 分；紀錄表只問「達到洞察？」</td><td>參與者先說、紀錄表改量過程（效果持久）</td></tr>\n        <tr><td>心智模型</td><td>「參與者需要專家幫他們看見意義」</td><td>帶領者改成「讓判斷看得見的人」（最根本）</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"partner\" hidden>\n      <p class=\"lead\">合作對象：合作的畫廊這次又延後付款。</p>\n      <table>\n        <tr><th>層</th><th>填進去的內容</th><th>只看這一層會做什麼</th></tr>\n        <tr><td>事件</td><td>這檔展覽結束 45 天還沒收到款；合約寫 30 天</td><td>再催一次（下次一樣）</td></tr>\n        <tr><td>模式</td><td>近一年四檔展覽都延 30–60 天；小型聯展延最久</td><td>每檔記「約定日／實付日」、提早看到</td></tr>\n        <tr><td>結構</td><td>合約沒寫逾期條款；對方會計每季結一次帳；我們沒人負責催款</td><td>合約加付款期限與逾期條款、指定催款人（效果持久）</td></tr>\n        <tr><td>心智模型</td><td>「小工作室不好意思催款」</td><td>把催款當合約履行，不當人情（最根本）</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"decision\" hidden>\n      <p class=\"lead\">一個決策：這個月又有 5 位家長問能不能加開平日班。</p>\n      <table>\n        <tr><th>層</th><th>填進去的內容</th><th>只看這一層會做什麼</th></tr>\n        <tr><td>事件</td><td>這個月 5 位家長問平日班；目前只有週末班</td><td>先回「暫時沒有」（下次一樣）</td></tr>\n        <tr><td>模式</td><td>每年暑假前詢問暴增、開學後回落；三年都一樣</td><td>記每月詢問數、提早看到季節性</td></tr>\n        <tr><td>結構</td><td>教室只有週末滿、平日閒置；老師都是兼職，平日排不出人</td><td>平日班排在兼職老師能接的時段、或找專任（效果持久）</td></tr>\n        <tr><td>心智模型</td><td>「擴大就是成長」</td><td>先定「成長」指什麼：人數、品質還是收入（最根本）</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"ecom\" hidden>\n      <p class=\"lead\">電商後台：這個月退貨率 12%，上個月 5%。</p>\n      <table>\n        <tr><th>層</th><th>填進去的內容</th><th>只看這一層會做什麼</th></tr>\n        <tr><td>事件</td><td>本月退貨率 12%（上月 5%）；退的多是尺寸類</td><td>客服加人處理退貨（下次一樣）</td></tr>\n        <tr><td>模式</td><td>每次上新品後兩週退貨衝高；尺寸類特別多；促銷檔期更嚴重</td><td>每週看「新品 × 退貨率」、提早看到</td></tr>\n        <tr><td>結構</td><td>商品頁尺寸表直接用供應商的、沒人核對；退貨流程只有「同意／不同意」，不問原因</td><td>上架前核對尺寸表、退貨表加「原因」欄（效果持久）</td></tr>\n        <tr><td>心智模型</td><td>「退貨是客人的問題，不是我們的問題」</td><td>把退貨當資料，不當麻煩（最根本）</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"daily\" hidden>\n      <p class=\"lead\">日常：這週又為了家事吵架。</p>\n      <table>\n        <tr><th>層</th><th>填進去的內容</th><th>只看這一層會做什麼</th></tr>\n        <tr><td>事件</td><td>週日晚上為了誰洗碗吵了 20 分鐘；這個月第 3 次</td><td>道歉、這次我洗（下次一樣）</td></tr>\n        <tr><td>模式</td><td>每次都在週日晚上；一忙就吵</td><td>記下每次吵架的時間和事、提早看到</td></tr>\n        <tr><td>結構</td><td>沒有分工表，誰看到誰做；週日晚上兩人都最累</td><td>排固定分工、把家事移出週日晚上（效果持久）</td></tr>\n        <tr><td>心智模型</td><td>「這種小事不用講」</td><td>小事講出來才不會變大事（最根本）</td></tr>\n      </table>\n    </div>\n    </div>\n    <p class=\"sub mt8 mb0\">每往下一層，看得到的解法就不一樣。工具做完分析後，你會得到一頁像這樣、但更完整的結果：</p>\n    <div class=\"btns mt8\"><button type=\"button\" class=\"btn primary\" data-note=\"做完的示範結果頁還在做：先按「用示範案例試一次」，再按「執行分析」，就會看到同一個案例做完的結果。\">看一個完整分析頁 →<small><span class=\"ex\" data-set=\"edd\">同一個案例，做完的九段結果</span><span class=\"ex\" data-set=\"partner\" hidden>這個領域的完整結果頁還在做</span><span class=\"ex\" data-set=\"decision\" hidden>這個領域的完整結果頁還在做</span><span class=\"ex\" data-set=\"ecom\" hidden>這個領域的完整結果頁還在做</span><span class=\"ex\" data-set=\"daily\" hidden>這個領域的完整結果頁還在做</span></small></button></div>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"fill\">下一個分頁：怎麼填 →</button><a class=\"btn primary\" href=\"/methods/systems.iceberg_model/run\">開始填我的案例 →</a></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-fill\" role=\"tabpanel\" aria-labelledby=\"tab-fill\" hidden>\n  <div class=\"card\">\n    <h2>怎麼填：四格，每格一個好例子和一個壞例子<small>1 分鐘</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>每步一好一壞，壞例括號裡寫的是它缺什麼。<b>你要做的</b>拿你的那件事，照「好」的樣子在心裡寫一句；寫不出來的那一層就是你要去補資料的層。</div>\n    <div class=\"step\"><div class=\"n\">1</div><div><b>把事件講清楚</b>：一件具體的事、有時間、有數字。\n      <div class=\"gb\"><div class=\"ex\" data-set=\"edd\"><div class=\"good\"><b>好</b>：第 6 次 session 8 人只有 2 人主動分享；第 1 次是 6 人。</div><div class=\"bad\"><b>壞</b>：大家都不認真。（哪一次？幾人？跟第 1 次比呢？）</div></div><div class=\"ex\" data-set=\"partner\" hidden><div class=\"good\"><b>好</b>：這檔展覽結束 45 天還沒收款，合約寫 30 天；上一檔延了 60 天。</div><div class=\"bad\"><b>壞</b>：他們老是拖。（哪一檔？幾天？合約寫幾天？）</div></div><div class=\"ex\" data-set=\"decision\" hidden><div class=\"good\"><b>好</b>：這個月 5 位家長問平日班；去年同月 2 位。</div><div class=\"bad\"><b>壞</b>：很多人在問。（幾位？哪個月？跟去年比呢？）</div></div><div class=\"ex\" data-set=\"ecom\" hidden><div class=\"good\"><b>好</b>：本月退貨率 12%，上月 5%；退的 70% 是尺寸類。</div><div class=\"bad\"><b>壞</b>：退貨變多了。（多少？哪一類？跟上月比呢？）</div></div><div class=\"ex\" data-set=\"daily\" hidden><div class=\"good\"><b>好</b>：週日晚上為了誰洗碗吵了 20 分鐘；這個月第 3 次。</div><div class=\"bad\"><b>壞</b>：我們最近常吵。（哪一天？為了什麼？幾次？）</div></div></div></div></div>\n    <div class=\"step\"><div class=\"n\">2</div><div><b>找模式</b>：這件事什麼時候發生、多常、跟什麼一起出現。\n      <div class=\"gb\"><div class=\"ex\" data-set=\"edd\"><div class=\"good\"><b>好</b>：三期都從第 4 次開始掉；帶領者先解讀的場次最低；線上場更低。</div><div class=\"bad\"><b>壞</b>：一直都這樣。（多久？多常？有什麼一起變？）</div></div><div class=\"ex\" data-set=\"partner\" hidden><div class=\"good\"><b>好</b>：近一年四檔都延 30–60 天；小型聯展延最久。</div><div class=\"bad\"><b>壞</b>：一直都這樣。（多久？多常？有什麼一起變？）</div></div><div class=\"ex\" data-set=\"decision\" hidden><div class=\"good\"><b>好</b>：每年暑假前詢問暴增、開學後回落；三年都一樣。</div><div class=\"bad\"><b>壞</b>：一直都有人問。（多久？多常？有什麼一起變？）</div></div><div class=\"ex\" data-set=\"ecom\" hidden><div class=\"good\"><b>好</b>：每次上新品後兩週退貨衝高；促銷檔期更嚴重。</div><div class=\"bad\"><b>壞</b>：常常這樣。（多久？多常？有什麼一起變？）</div></div><div class=\"ex\" data-set=\"daily\" hidden><div class=\"good\"><b>好</b>：每次都在週日晚上；一忙就吵。</div><div class=\"bad\"><b>壞</b>：一直都這樣。（多久？多常？有什麼一起變？）</div></div></div></div></div>\n    <div class=\"step\"><div class=\"n\">3</div><div><b>找結構</b>：哪個流程、規則、人力安排在製造這個模式。寫「制度」，不寫「某個人」。\n      <div class=\"gb\"><div class=\"ex\" data-set=\"edd\"><div class=\"good\"><b>好</b>：帶領者先講意義、說明佔 35 分；紀錄表只問「達到洞察？」。</div><div class=\"bad\"><b>壞</b>：某某帶領者不重視。（這是怪人，不是結構）</div></div><div class=\"ex\" data-set=\"partner\" hidden><div class=\"good\"><b>好</b>：合約沒寫逾期條款；對方會計每季結一次帳；我們沒人負責催。</div><div class=\"bad\"><b>壞</b>：他們會計很混。（這是怪人，不是結構）</div></div><div class=\"ex\" data-set=\"decision\" hidden><div class=\"good\"><b>好</b>：教室只有週末滿；老師都是兼職，平日排不出人。</div><div class=\"bad\"><b>壞</b>：老師不配合。（這是怪人，不是結構）</div></div><div class=\"ex\" data-set=\"ecom\" hidden><div class=\"good\"><b>好</b>：尺寸表直接用供應商的、沒人核對；退貨表不問原因。</div><div class=\"bad\"><b>壞</b>：客服不夠細心。（這是怪人，不是結構）</div></div><div class=\"ex\" data-set=\"daily\" hidden><div class=\"good\"><b>好</b>：沒有分工表，誰看到誰做；週日晚上兩人都最累。</div><div class=\"bad\"><b>壞</b>：對方很懶。（這是怪人，不是結構）</div></div></div></div></div>\n    <div class=\"step\"><div class=\"n\">4</div><div><b>問信念</b>：大家沒說出口、但決定規則和優先順序的那句話。也問問自己的。\n      <div class=\"gb\"><div class=\"ex\" data-set=\"edd\"><div class=\"good\"><b>好</b>：「參與者需要專家幫他們看見意義。」</div><div class=\"bad\"><b>壞</b>：大家心態不對。（太籠統，指不出哪個假設）</div></div><div class=\"ex\" data-set=\"partner\" hidden><div class=\"good\"><b>好</b>：「小工作室不好意思催款。」</div><div class=\"bad\"><b>壞</b>：我們太軟弱。（太籠統，指不出哪個假設）</div></div><div class=\"ex\" data-set=\"decision\" hidden><div class=\"good\"><b>好</b>：「擴大就是成長。」</div><div class=\"bad\"><b>壞</b>：我們不夠有企圖心。（太籠統，指不出哪個假設）</div></div><div class=\"ex\" data-set=\"ecom\" hidden><div class=\"good\"><b>好</b>：「退貨是客人的問題，不是我們的問題。」</div><div class=\"bad\"><b>壞</b>：大家不重視品質。（太籠統，指不出哪個假設）</div></div><div class=\"ex\" data-set=\"daily\" hidden><div class=\"good\"><b>好</b>：「這種小事不用講。」</div><div class=\"bad\"><b>壞</b>：我們個性不合。（太籠統，指不出哪個假設）</div></div></div></div></div>\n    <p class=\"sub mt8 mb0\">填不出某一層沒關係，留白比硬湊好；工具會把它列成「證據缺口」，告訴你該去補什麼資料。</p>\n  </div>\n\n  <div class=\"card\">\n    <h2>常見錯誤<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>四條，每條都是「看起來對、其實錯」。<b>你要做的</b>對照你上面心裡寫的那幾句，看有沒有中。</div>\n    <div class=\"mistake\"><i>✕</i><span><b>急著怪人</b>：一直問「是誰」，就挖不到「為什麼」。結構層要寫制度，不寫名字。</span></div>\n    <div class=\"mistake\"><i>✕</i><span><b>跳層</b>：從事件直接跳到「他們心態有問題」。中間的模式和結構才是能動手改的地方。</span></div>\n    <div class=\"mistake\"><i>✕</i><span><b>把模式當原因</b>：<span class=\"ex\" data-set=\"edd\">「每期第 4 次之後分享變少」是模式，不是原因；原因是第 4 次之後流程哪裡變了。</span><span class=\"ex\" data-set=\"partner\" hidden>「每檔展覽都延後付款」是模式，不是原因；原因是合約和結帳流程哪裡讓它一再發生。</span><span class=\"ex\" data-set=\"decision\" hidden>「每年暑假前詢問暴增」是模式，不是原因；原因是教室和排班怎麼安排才讓它每年重演。</span><span class=\"ex\" data-set=\"ecom\" hidden>「每次上新品退貨就衝高」是模式，不是原因；原因是上架和退貨流程哪裡漏了。</span><span class=\"ex\" data-set=\"daily\" hidden>「每次都在週日晚上吵」是模式，不是原因；原因是那個晚上的安排哪裡讓兩個人都最累。</span></span></div>\n    <div class=\"mistake\"><i>✕</i><span><b>只看別人的假設</b>：你自己也在這個系統裡；你的假設也要寫進第四層。</span></div>\n    <div class=\"quiz\"><b>自我檢查（30 秒，點開看答案）</b>\n      <div class=\"ex\" data-set=\"edd\">\n        <details><summary>「每期第 4 次之後分享變少」是哪一層？</summary>模式：一再發生的型態，不是原因。</details>\n        <details><summary>「紀錄表只問有沒有達到洞察」是哪一層？</summary>結構：是制度在製造模式。</details>\n        <details><summary>「參與者需要專家幫他們看見意義」是哪一層？</summary>心智模型：沒說出口、撐住制度的信念。</details>\n      </div>\n      <div class=\"ex\" data-set=\"partner\" hidden>\n        <details><summary>「每檔展覽結束都延後付款」是哪一層？</summary>模式：一再發生的型態，不是原因。</details>\n        <details><summary>「合約沒寫逾期條款」是哪一層？</summary>結構：是制度在製造模式。</details>\n        <details><summary>「小工作室不好意思催款」是哪一層？</summary>心智模型：沒說出口、撐住制度的信念。</details>\n      </div>\n      <div class=\"ex\" data-set=\"decision\" hidden>\n        <details><summary>「每年暑假前詢問暴增」是哪一層？</summary>模式：一再發生的型態，不是原因。</details>\n        <details><summary>「老師都是兼職，平日排不出人」是哪一層？</summary>結構：是制度在製造模式。</details>\n        <details><summary>「擴大就是成長」是哪一層？</summary>心智模型：沒說出口、撐住制度的信念。</details>\n      </div>\n      <div class=\"ex\" data-set=\"ecom\" hidden>\n        <details><summary>「每次上新品後兩週退貨衝高」是哪一層？</summary>模式：一再發生的型態，不是原因。</details>\n        <details><summary>「退貨流程不問原因」是哪一層？</summary>結構：是制度在製造模式。</details>\n        <details><summary>「退貨是客人的問題」是哪一層？</summary>心智模型：沒說出口、撐住制度的信念。</details>\n      </div>\n      <div class=\"ex\" data-set=\"daily\" hidden>\n        <details><summary>「每次都在週日晚上吵」是哪一層？</summary>模式：一再發生的型態，不是原因。</details>\n        <details><summary>「沒有分工表，誰看到誰做」是哪一層？</summary>結構：是制度在製造模式。</details>\n        <details><summary>「這種小事不用講」是哪一層？</summary>心智模型：沒說出口、撐住制度的信念。</details>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"read\">下一個分頁：看懂結果 →</button><a class=\"btn primary\" href=\"/methods/systems.iceberg_model/run\">開始填我的案例 →</a></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-read\" role=\"tabpanel\" aria-labelledby=\"tab-read\" hidden>\n  <div class=\"card\">\n    <h2>看懂結果：按「執行分析」之後那一頁怎麼讀<small>1 分鐘</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先看三步讀法，再對照下面的九段；結果頁每段開頭只留一句，詳細讀法都在這裡。<b>你要做的</b>不用做；結果頁哪一段看不懂，回這個分頁找同一個編號。</div>\n    <div class=\"todos\">\n      <div class=\"todo\"><b>① 先看結論與冰山圖</b>一句話結論、三個發現；再看你填的四段話各在哪一層。</div>\n      <div class=\"todo\"><b>② 看圖表與四張卡</b>趨勢圖、因果回饋圖、槓桿對比；四張卡同一格式：這層問什麼 → 你填了什麼 → 這代表什麼 → 在這層出手會怎樣。</div>\n      <div class=\"todo\"><b>③ 看總結、解決方案、下一步</b>最有力的出手點在哪一層；三個方案比一比；90 天行動計畫與三個追蹤指標；接著做什麼，不做也可以。</div>\n    </div>\n    <p class=\"sub mt8\">只有 30 秒？看 ① 的一句話和建議就夠。</p>\n    <div class=\"terms\"><b>四個詞：</b><span><b>事件</b> 這次發生的事</span><span><b>模式</b> 一再發生</span><span><b>結構</b> 為什麼一再</span><span><b>心智模型</b> 為什麼沒人改</span></div>\n    <h3 class=\"fam\">頁首和九段，每段回答一件事</h3>\n    <div class=\"row\"><b>頁首</b><span>上面是你填的四個格子（改了可以重跑），右上角「怎麼用？」開這堂課。狀態列說草稿還是已核准、資料有多少（你填的幾段、外部來源幾筆）、四層完整度、花費；資料少，結論的信心就低。</span></div>\n    <div class=\"row\"><b>① 結論</b><span>一句話＋三個發現，每個發現標信心（高／中／低）和理由；「改判條件」= 出現哪些證據就要改結論。最下面寫你自己的判斷（同意／部分同意／不同意）：你的原話才是紀錄，AI 寫的只是附掛。</span></div>\n    <div class=\"row\"><b>② 冰山圖</b><span>左邊是每層要回答的問題和你填的內容，右邊是在這層出手的方式；★ 是建議先出手的層。圖下的「資料厚度」說哪一層填得最薄；放錯層就回上面改，再執行一次。</span></div>\n    <div class=\"row\"><b>③ 圖表分析</b><span>三張圖各回答一個問題：趨勢（真的在變嗎）、因果迴路（是什麼在推）、槓桿（在哪一層出手最值得）。每張圖下有「怎麼看／看到／注意／來源」；標「示意」的圖要接上真實資料才算數。</span></div>\n    <div class=\"row\"><b>④ 四層解讀</b><span>四張卡同一格式：這層問 → 你填的 → 這代表 → 在這層出手（附槓桿：低／中低／高／最高）→ 對應 ⑦ 的方案 → 資料厚度。找出最薄的一層，之後補資料。</span></div>\n    <div class=\"row\"><b>⑤ 總結</b><span>三句話：問題在哪、先做哪層、還缺什麼（證據缺口）。缺口裡的資料你手上有，就回上面補、再執行一次。</span></div>\n    <div class=\"row\"><b>⑥ 對照表</b><span>一列一層：出手方式、時間取向、這層問的問題、你的案例、建議動作。越往下越慢越難，但越根本；四列都要有人負責，負責人填在 ⑦ 的 B 表。</span></div>\n    <div class=\"row\"><b>⑦ 解決方案</b><span>A 三條路比一比 → B 排成 90 天行動計畫 → C 三個指標盯著、90 天後自動重跑。表裡的字：見效 = 多久看得到；成本 = 要投入什麼；持久度 = 會不會回彈；風險 = 最可能失敗的地方。目標數字由你定，系統只帶入現況。</span></div>\n    <div class=\"row\"><b>⑧ 下一步</b><span>旅程列是你在哪；每張卡寫做了會得到什麼、會自動帶入什麼、還要你填幾格。可以選一張、把建議的幾步串成工作流，或都不做。</span></div>\n    <div class=\"row\"><b>⑨ 引註與核准</b><span>[n] 是那句話的來源：「你的輸入」= 你填的原文，「外部來源」= 抓來的網頁（網址、抓取時間、指紋）。最下面：核准 = 成為專案的正式紀錄；退回 = 寫原因重做，這一版保留；專家模式收著閘門表與 JSON。</span></div>\n  </div>\n  <div class=\"tabnext\"><a class=\"btn primary\" href=\"/methods/systems.iceberg_model/run\">開始填我的案例 →</a><button type=\"button\" class=\"btn\" data-note=\"做完的示範結果頁還在做：先按「用示範案例試一次」，再按「執行分析」，就會看到同一個案例做完的結果。\">對照一個做完的結果頁 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-teach\" role=\"tabpanel\" aria-labelledby=\"tab-teach\" hidden>\n  <div class=\"card\">\n    <h2>教材版：給老師／帶領者<small>同一份資料，另一種排版</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>其他分頁是學員版（5 分鐘自學）；這裡把同一堂課排成 45 分鐘課堂：流程、講稿要點、討論題、學員常錯、講義。<b>你要做的</b>只在你要教別人時展開；可整份匯出成講義與投影片大綱。</div>\n    <details><summary><b>課堂流程（45 分鐘）</b></summary>\n      <table class=\"mt6\">\n        <tr><th>分</th><th>做什麼</th><th>用學員版哪一頁</th></tr>\n        <tr><td>0–5</td><td>破冰：每人說一件「最近一再發生」的事</td><td>「認識」的「什麼時候用」</td></tr>\n        <tr><td>5–15</td><td>講四層，例子換成學員的領域</td><td>「認識」（切領域）</td></tr>\n        <tr><td>15–30</td><td>分組把自己的案例填成四層；用好壞例當互評表</td><td>「怎麼填」</td></tr>\n        <tr><td>30–40</td><td>各組報告；其他組專門找「跳層」和「怪人」</td><td>「怎麼填」的常見錯誤</td></tr>\n        <tr><td>40–45</td><td>收尾：填不出的那一層就是要補資料的層；帶大家看一次結果頁；預告下一步工具</td><td>「開始」卡、「看懂結果」、結果頁 ⑧</td></tr>\n      </table>\n    </details>\n    <details><summary><b>講稿要點（每步 2–3 句）</b></summary>\n      <ul class=\"check\">\n        <li>這是什麼：先問「你們最近有沒有一件事換了人、換了工具還是一直發生」，再給冰山圖。不要先講定義。</li>\n        <li>四層：用「一次／一再／為什麼一再／為什麼沒人改」四個詞帶，每層停 30 秒讓學員對到自己的案例。</li>\n        <li>做完的例子：只講「每往下一層，解法就不一樣」，不要解釋案例細節。</li>\n        <li>怎麼填：把壞例投影出來，讓學員說哪裡缺，再翻出好例。</li>\n        <li>常見錯誤：「怪人」和「跳層」一定親自示範一次錯的寫法。</li>\n        <li>開始：告訴學員填不出來的層留白，工具會把它列成證據缺口，不是失敗。</li>\n      </ul>\n    </details>\n    <details><summary><b>討論題（3 題）</b></summary>\n      <ol class=\"src\">\n        <li>你的案例裡，哪一層是你最不想寫的？為什麼？</li>\n        <li>如果只能改一層，你選哪一層？三個月後怎麼知道有沒有用？</li>\n        <li>你自己在這個系統裡的假設是什麼？寫進第四層了嗎？</li>\n      </ol>\n    </details>\n    <details><summary><b>學員最常錯的三件事，怎麼接</b></summary>\n      <ul class=\"check\">\n        <li>把模式寫成原因 → 反問：「這件事多久一次？什麼時候特別多？」把它推回第 2 層。</li>\n        <li>結構層寫人名 → 反問：「如果換一個人，還會發生嗎？」會，就是結構。</li>\n        <li>第四層寫「態度有問題」 → 反問：「他們相信什麼，才會這樣安排？」要一句可以被否證的話。</li>\n      </ul>\n    </details>\n    <details><summary><b>講義與投影片</b></summary>\n      <p class=\"my6\">列印版講義 = 第 2 步四層表（學員領域版）＋第 4 步好壞例＋一張空白四格工作單；投影片大綱 = 六步各一頁＋冰山圖一頁。兩者都從這一頁匯出（匯出功能還在做）。</p>\n    </details>\n    <p class=\"sub mt8 mb0\">教材版和學員版由同一份工具資料生成（來源 [1]–[3]），改課文就同時改兩版。藝術反思工具的帶領腳本（Airtable 的「帶活動者提示用語」「時間分段」「停止活動訊號」）會直接進這一段。</p>\n  </div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-sources\" role=\"tabpanel\" aria-labelledby=\"tab-sources\" hidden>\n  <div class=\"card\">\n    <h2>課程來源（每段課文的 [n]）</h2>\n    <div class=\"how\"><b>怎麼讀</b>[n] 是那段課文的依據；來源不足的工具會在頂端顯示「知識不足：缺哪幾項」。<b>你要做的</b>不用做；發現寫錯可以回報。</div>\n    <ol class=\"src\">\n      <li>The Systems Thinking，「Iceberg Model」教學（定義 → 四層 → 例子 → 步驟 → 常見錯誤的課程結構；本課改寫，非轉載）</li>\n      <li>untools.co，「Iceberg Model」（定義與四層名稱；工具資料裡的權威網址）</li>\n      <li>NPC 冰山工作單（每層要回答的問題與介入動詞：回應／預測／設計／轉化）</li>\n    </ol>\n    <p class=\"sub\">課文由工具自己的資料庫（來源、契約、範例）生成並由人審定；之後每個工具都用同一套規則產生自己的課。</p>\n  </div>\n  </section>\n" },
  "life-decision-v1": { kind: "workflow", href: "/learn/workflow/life-decision-v1", title: "做一個決定（3 站）：開始前 3 分鐘", html: "  <div class=\"crumbs\"><a href=\"/workflows\">工作流</a> › <a href=\"/workflows#wf-life-decision-v1\">做一個決定</a> › 3 分鐘課</div>\n\n  <div class=\"top\">\n    <div>\n      <h1>做一個決定（3 站）：開始前 3 分鐘</h1>\n      <div class=\"sub\">想直接走，按下面的「開始我的決定」；想先學，照分頁一頁一頁看，每頁不到一分鐘。</div>\n    </div>\n  </div>\n  <div class=\"status\"><span class=\"pill ok\">三站工具齊備 M1–M11 ✓</span><span>課程來源 2 筆 <cite>[1]</cite><cite>[2]</cite></span><span>約 3 分鐘</span><span>學完你會：知道這條路解哪種決定、每站要你填什麼、看懂總覽頁、什麼時候該停下來改</span><span>教材版在「教材版」分頁（給老師／帶領者）</span></div>\n\n  <div class=\"card cta\" id=\"start\">\n    <h2>開始：走你自己的決定<small>準備 20 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>這張卡一直在最上面；下面的分頁是課程，看完或看到一半都能回來按。<b>你要做的</b>按「開始我的決定」；還不確定，先用示範案例走一次，或按第三顆讓系統幫你挑。</div>\n    <div class=\"btns\">\n      <button type=\"button\" class=\"btn primary big\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →<small>第 1 站三個空格子，每格旁邊有提示和例子；按「執行這一站」才開始</small></button>\n      <button type=\"button\" class=\"btn\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">用示範案例走一次<small><span class=\"ex\" data-set=\"edd\">混合制那個例子，第 1 站已填好，按執行就走到第 2 站</span><span class=\"ex\" data-set=\"partner\" hidden>續約畫廊那個例子，第 1 站已填好，按執行就走到第 2 站</span><span class=\"ex\" data-set=\"decision\" hidden>加開平日班那個例子，第 1 站已填好，按執行就走到第 2 站</span><span class=\"ex\" data-set=\"ecom\" hidden>尺寸類改預購那個例子，第 1 站已填好，按執行就走到第 2 站</span><span class=\"ex\" data-set=\"daily\" hidden>家事服務那個例子，第 1 站已填好，按執行就走到第 2 站</span></small></button>\n      <a class=\"btn ghost\" href=\"/#ask\">這條路適合我的問題嗎？<small>描述你的問題，系統幫你挑，最多三個建議</small></a>\n    </div>\n    <p>手邊有這些會走得比較快，沒有也可以先走、之後補：</p>\n    <ul class=\"check\">\n      <li>你要決定的那件事，一句話</li>\n      <li>兩個以上的選項</li>\n      <li>成功長什麼樣（2–3 個看得到的條件）</li>\n      <li>你在乎什麼（之後變成準則和權重）</li>\n    </ul>\n    <p class=\"sub mb0\">這堂課之後不會再自動出現；每一站的工具課只在你第一次到那一站時出現一次。想再看，總覽頁右上角「怎麼用？」隨時能打開，會另開一個分頁，填到一半的格子不會不見。</p>\n  </div>\n\n    <div class=\"chips\" role=\"tablist\" aria-label=\"例子領域\">\n      <span class=\"sub\">例子領域：</span>\n      <button class=\"chip on\" role=\"tab\" aria-selected=\"true\" data-set=\"edd\" id=\"chip-edd\">藝術反思／EdD 研究（你的預設）</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"partner\" id=\"chip-partner\">合作對象</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"decision\" id=\"chip-decision\">一個決策</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"ecom\" id=\"chip-ecom\">電商後台</button>\n      <button class=\"chip\" role=\"tab\" aria-selected=\"false\" data-set=\"daily\" id=\"chip-daily\">日常</button>\n    </div>\n  <div class=\"tabs\" role=\"tablist\" aria-label=\"課程內容\">\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-learn\" aria-controls=\"panel-learn\" aria-selected=\"true\" tabindex=\"0\">認識<small>30 秒</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-stations\" aria-controls=\"panel-stations\" aria-selected=\"false\" tabindex=\"-1\">各站<small>1 分</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-example\" aria-controls=\"panel-example\" aria-selected=\"false\" tabindex=\"-1\">看例子<small>30 秒</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-walk\" aria-controls=\"panel-walk\" aria-selected=\"false\" tabindex=\"-1\">怎麼走<small>30 秒</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-read\" aria-controls=\"panel-read\" aria-selected=\"false\" tabindex=\"-1\">看懂總覽<small>30 秒</small></button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-teach\" aria-controls=\"panel-teach\" aria-selected=\"false\" tabindex=\"-1\">教材版</button>\n    <button class=\"tab\" type=\"button\" role=\"tab\" id=\"tab-sources\" aria-controls=\"panel-sources\" aria-selected=\"false\" tabindex=\"-1\">來源</button>\n  </div>\n\n  <section class=\"tabpanel\" id=\"panel-learn\" role=\"tabpanel\" aria-labelledby=\"tab-learn\">\n  <div class=\"card\">\n    <h2>這條路解什麼問題<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先看「能回答／不能回答」，再看站列。<b>你要做的</b>不用做；你的問題如果不是「幾個選項選一個」，這條路不適合，去最上面「開始」卡按第三顆按鈕。</div>\n    <p class=\"lead\">「做一個決定」把一個<b>要在幾個選項裡選一個</b>的問題，走三站：先把問題講清楚，再看自己的強弱與外面的機會威脅，最後用<b>你自己定的準則和權重</b>把選項打分 <cite>[1]</cite>。</p>\n    <div class=\"grid2c\">\n      <div class=\"can\"><b>這條路能回答</b>要決定的到底是什麼、成功長什麼樣；我們的強弱、外面的機會威脅；幾個選項按你的準則哪個最好、哪個權重一改結果就翻。</div>\n      <div class=\"cant\"><b>這條路不能回答</b>市場會不會買單（除非接上資料蒐集）；權重不會替你定，那是你的價值判斷；「該不該」的道德問題。</div>\n    </div>\n    <div class=\"journey\"><span>第 1 站 問題陳述</span><i>→</i><span>第 2 站 SWOT</span><i>→</i><span>第 3 站 加權決策矩陣</span><i>→</i><span>總結頁</span></div>\n    <p class=\"sub\">什麼時候用：選項已經有兩個以上、大家意見不一、想要一個能說清楚理由的決定。什麼時候不用：只有一個選項（那是「做不做」，用可行性那條路）；還不知道問題是什麼（先單獨跑問題陳述）。</p>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"stations\">下一個分頁：各站 →</button><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-stations\" role=\"tabpanel\" aria-labelledby=\"tab-stations\" hidden>\n  <div class=\"card\">\n    <h2>三站各做什麼、系統幫你填什麼、你要填什麼<small>1 分鐘</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先在分頁上面按你的領域，例子就會換成你熟的情境；每一站從上往下看：這站在做什麼 → 你會看到的表單 → 已經幫你填好的 → 你要填的（附一個填好的例子）→ 做完會得到什麼 → 完整介紹的連結。這堂課只講「這條路」，每個工具的深度在它自己的正式課。<b>你要做的</b>按一個領域（每個分頁的例子都會跟著換）；把你自己的決定，照例子的樣子在心裡填一次。</div>\n    <div id=\"examples\">\n\n      <div class=\"station\">\n        <h3>第 1 站 問題陳述</h3>\n        <p class=\"why\">先把「到底要決定什麼」講清楚。這一站省掉，後面兩站常常在幫不同的問題打分。</p>\n        <div class=\"row\"><b>你會看到</b><span>三個格子：要決定什麼、誰受影響、成功長什麼樣。每格旁邊有提示，也可以按「用示範案例」。</span></div>\n        <div class=\"row\"><b>已經幫你填</b><span>你建立專案時寫的那段話，會出現在第一格，你改就好。</span></div>\n        <div class=\"row\"><b class=\"need\">你要填</b><div>誰受影響（具體到人數或角色）、成功的 2–3 個條件（要看得到、量得到）。\n          <div class=\"ex filled\" data-set=\"edd\"><span class=\"lab\">填好的例子（藝術反思）</span><b>要決定什麼：</b>WuSheng 團體課要不要從全實體改成「線上＋實體」混合。<br><b>誰受影響：</b>現有 8 位參與者、2 位帶領者、3 位遠地詢問者。<br><b>成功條件：</b>① 主動分享人數不低於現在（每場 6 人）；② 遠地至少 3 人能參加；③ 帶領者每週準備時間不超過現在的 1.2 倍。</div>\n          <div class=\"ex filled\" data-set=\"partner\" hidden><span class=\"lab\">填好的例子（合作對象）</span><b>要決定什麼：</b>下一檔展覽要不要續約那家近一年每檔都延後付款的畫廊。<br><b>誰受影響：</b>工作室的 3 位創作者、負責催款的行政 1 人、對方的展務。<br><b>成功條件：</b>① 展覽結束 30 天內收到款；② 作品曝光不低於現在（每檔到場 ≥ 200 人）；③ 我們的行政時間不增加。</div>\n          <div class=\"ex filled\" data-set=\"decision\" hidden><span class=\"lab\">填好的例子（一個決策）</span><b>要決定什麼：</b>要不要加開平日班（這個月 5 位家長問）。<br><b>誰受影響：</b>詢問的 5 個家庭、3 位兼職老師、教室排程。<br><b>成功條件：</b>① 平日班開課後 ≥ 6 人；② 老師平日排得出來、不加班；③ 半年內不虧錢。</div>\n          <div class=\"ex filled\" data-set=\"ecom\" hidden><span class=\"lab\">填好的例子（電商後台）</span><b>要決定什麼：</b>退貨率 12% 的尺寸類商品，要不要改成預購制（下單後 7 天出貨、先確認尺寸）。<br><b>誰受影響：</b>客服 1 人、倉庫、常買尺寸類的老客人。<br><b>成功條件：</b>① 三個月內尺寸類退貨率 ≤ 5%；② 毛利不低於現在；③ 客服每週工時不增加。</div>\n          <div class=\"ex filled\" data-set=\"daily\" hidden><span class=\"lab\">填好的例子（日常）</span><b>要決定什麼：</b>要不要每兩週請一次家事服務，讓週日晚上不再為家事吵架。<br><b>誰受影響：</b>自己、同住的伴侶。<br><b>成功條件：</b>① 一個月內週日晚上零吵架；② 每月多花不超過 NT$3,000；③ 兩個人都同意這個安排。</div>\n        </div></div>\n        <div class=\"row\"><b>做完會得到</b><span>一句清楚的問題陳述＋成功條件清單。後面兩站都拿它當基準，總結頁也用它來判斷「決定有沒有達成目的」。</span></div>\n        <div class=\"row\"><b>常見卡點</b><span>成功條件寫成「希望變好」。改成看得到的數字或事實，例如「每場主動分享 ≥ 6 人」。</span></div>\n        <div class=\"row\"><b>大約</b><span>2 分鐘・NT$1</span></div>\n        <div class=\"row\"><b>完整介紹</b><span>這一站的工具有自己的正式課（5 分鐘學員版＋底部教材版），第一次到站時會自動出現，也可以先看：<a href=\"/methods/framing.problem_statement\">問題陳述：完整介紹 →</a>。這裡只簡述，深度在那一頁。</span></div>\n      </div>\n\n      <div class=\"station\">\n        <h3>第 2 站 SWOT</h3>\n        <p class=\"why\">看自己（強項、弱項）和外面（機會、威脅）。這四格之後會自動變成第 3 站打分用的準則。</p>\n        <div class=\"row\"><b>你會看到</b><span>一個「脈絡」欄（已填好）＋四個格子 S／W／O／T，每格可以加多條，旁邊有「讓 AI 起草」。</span></div>\n        <div class=\"row\"><b>已經幫你填</b><span>第 1 站的問題陳述和三個成功條件，自動放進「脈絡」；你不用重打。</span></div>\n        <div class=\"row\"><b class=\"need\">你要填</b><div>S／W／O／T 各至少 2 條。寫事實，不寫感覺；每條最好能對到第 1 站的某個成功條件。可以先讓 AI 起草，再刪改。\n          <div class=\"ex filled\" data-set=\"edd\"><span class=\"lab\">填好的例子（藝術反思）</span><b>S 強項：</b>帶領者熟線上工具；作品照片流程已經數位化。<br><b>W 弱項：</b>只有一間教室；線上設備老舊。<br><b>O 機會：</b>遠地需求是真的（3 人詢問）；線上場可以錄影回看。<br><b>T 威脅：</b>線上人數一多，主動分享就掉（上一期線上場最低）；混合制兩邊都要顧，帶領者負擔可能超過 1.2 倍。</div>\n          <div class=\"ex filled\" data-set=\"partner\" hidden><span class=\"lab\">填好的例子（合作對象）</span><b>S 強項：</b>作品有固定藏家；近三檔都完售。<br><b>W 弱項：</b>只有 1 位行政，沒人專門催款。<br><b>O 機會：</b>另一家畫廊主動邀展；自辦展的場地有補助。<br><b>T 威脅：</b>這家畫廊近一年四檔都延 30–60 天付款；換畫廊要重新累積藏家。</div>\n          <div class=\"ex filled\" data-set=\"decision\" hidden><span class=\"lab\">填好的例子（一個決策）</span><b>S 強項：</b>週末班口碑好、候補 8 人。<br><b>W 弱項：</b>老師都是兼職，平日排班不穩。<br><b>O 機會：</b>5 位家長已經在問；暑假前需求最高。<br><b>T 威脅：</b>每年開學後詢問回落；平日班不到 6 人就虧。</div>\n          <div class=\"ex filled\" data-set=\"ecom\" hidden><span class=\"lab\">填好的例子（電商後台）</span><b>S 強項：</b>供應商穩定；後台能批次改商品設定。<br><b>W 弱項：</b>客服只有 1 人；退貨表不問原因。<br><b>O 機會：</b>同業改預購後，尺寸類退貨率降到 4%。<br><b>T 威脅：</b>預購讓出貨變慢，旺季客訴會增加；老客人可能改買別家。</div>\n          <div class=\"ex filled\" data-set=\"daily\" hidden><span class=\"lab\">填好的例子（日常）</span><b>S 強項：</b>兩個人都想解決，不是只有一方在意。<br><b>W 弱項：</b>這一季預算緊。<br><b>O 機會：</b>社區有評價好、按次計費的服務。<br><b>T 威脅：</b>費用每年在漲；其中一人不習慣外人進家門。</div>\n        </div></div>\n        <div class=\"row\"><b>做完會得到</b><span>SWOT 表＋每一格的證據強度（哪幾條只是感覺、哪幾條有數字），以及自動整理出來的「第 3 站準則候選」。</span></div>\n        <div class=\"row\"><b>常見卡點</b><span>把「希望」寫進機會、把「擔心」寫進威脅。機會和威脅是外面已經存在的事，不是心情。</span></div>\n        <div class=\"row\"><b>大約</b><span>3 分鐘・NT$1</span></div>\n        <div class=\"row\"><b>完整介紹</b><span>這一站的工具有自己的正式課（5 分鐘學員版＋底部教材版），第一次到站時會自動出現，也可以先看：<a href=\"/methods/strategy.swot\">SWOT 分析：完整介紹 →</a>。這裡只簡述，深度在那一頁。</span></div>\n      </div>\n\n      <div class=\"station\">\n        <h3>第 3 站 加權決策矩陣</h3>\n        <p class=\"why\">幾個選項，按你自己定的準則和權重打分。分數是「按你的權重」算的，所以最重要的是權重由你填。</p>\n        <div class=\"row\"><b>你會看到</b><span>左邊是準則（已從第 2 站帶入），每個準則旁邊一個權重格（1–5）；上面是選項；中間是分數表；下面有「敏感度」：哪個權重一改，結果就翻。</span></div>\n        <div class=\"row\"><b>已經幫你填</b><span>準則候選（從第 2 站的四格整理出來）和選項候選（從第 1 站的問題抓出來）。分數可以讓 AI 起草。</span></div>\n        <div class=\"row\"><b class=\"need\">你要填</b><div>每個準則的權重（1–5）。這是你的價值判斷，系統不會代填，也不會建議數字。\n          <div class=\"ex filled\" data-set=\"edd\"><span class=\"lab\">填好的例子（藝術反思）</span><b>選項：</b>維持全實體／全線上／混合（每場線上 ≤ 4 人）。<br><b>準則與權重：</b>主動分享不降 5、遠地可參加 3、帶領者負擔 4、設備成本 2。<br><b>結果：</b>混合最高分；但「主動分享不降」的權重從 5 改成 3，全線上就贏 → 這個權重是關鍵，要想清楚。</div>\n          <div class=\"ex filled\" data-set=\"partner\" hidden><span class=\"lab\">填好的例子（合作對象）</span><b>選項：</b>續約並加逾期條款／換到邀展的那家畫廊／自辦展覽。<br><b>準則與權重：</b>付款準時 5、曝光 4、行政負擔 3、藏家關係 2。<br><b>結果：</b>續約＋逾期條款最高分；但「曝光」的權重從 4 改成 2，自辦展覽就贏 → 這個權重是關鍵，要想清楚。</div>\n          <div class=\"ex filled\" data-set=\"decision\" hidden><span class=\"lab\">填好的例子（一個決策）</span><b>選項：</b>不開／開一班試半年／找專任老師開兩班。<br><b>準則與權重：</b>老師排得出 5、人數 4、不虧錢 4、品質 3。<br><b>結果：</b>開一班試半年最高分；但「老師排得出」的權重從 5 改成 3，開兩班就贏 → 這個權重是關鍵，要想清楚。</div>\n          <div class=\"ex filled\" data-set=\"ecom\" hidden><span class=\"lab\">填好的例子（電商後台）</span><b>選項：</b>維持現狀／尺寸類改預購／尺寸類只留無尺寸款。<br><b>準則與權重：</b>退貨率 5、毛利 4、出貨速度 3、客服負擔 3。<br><b>結果：</b>改預購最高分；但「出貨速度」的權重從 3 改成 5，維持現狀就贏 → 這個權重是關鍵，要想清楚。</div>\n          <div class=\"ex filled\" data-set=\"daily\" hidden><span class=\"lab\">填好的例子（日常）</span><b>選項：</b>不請／每兩週一次／每週一次。<br><b>準則與權重：</b>週日晚上不吵 5、費用 4、隱私 3、公平 3。<br><b>結果：</b>每兩週一次最高分；但「費用」的權重從 4 改成 5，不請就贏 → 這個權重是關鍵，要想清楚。</div>\n        </div></div>\n        <div class=\"row\"><b>做完會得到</b><span>分數表、敏感度分析（哪個權重是關鍵）、然後是總結頁：三站合一的一句話、最終建議、解決方案與追蹤。</span></div>\n        <div class=\"row\"><b>常見卡點</b><span>權重讓 AI 填，或所有準則都填 5。權重不一樣，這張表才有意義。</span></div>\n        <div class=\"row\"><b>大約</b><span>3 分鐘・NT$1</span></div>\n        <div class=\"row\"><b>完整介紹</b><span>這一站的工具有自己的正式課（5 分鐘學員版＋底部教材版），第一次到站時會自動出現，也可以先看：<a href=\"/methods/decision.weighted_decision_matrix\">加權決策矩陣：完整介紹 →</a>。這裡只簡述，深度在那一頁。</span></div>\n      </div>\n\n    </div>\n    <p class=\"sub mt10 mb0\">記法：第 1 站定「要決定什麼」，第 2 站看「自己和外面」，第 3 站「用你的權重打分」。每一站都只填紅字那一列，其他系統從上一站帶來。例子跟著你進來的那條線走；不會拿你真實填過的案例當教材。</p>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"example\">下一個分頁：看例子 →</button><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-example\" role=\"tabpanel\" aria-labelledby=\"tab-example\" hidden>\n  <div class=\"card\">\n    <h2>看一個走完的例子<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>每站一句話，最後一句是三站合一。<b>你要做的</b>不用做；想看完整總覽按按鈕。</div>\n    <div id=\"walked\">\n    <div class=\"ex\" data-set=\"edd\">\n      <p class=\"lead\">團體反思：WuSheng 課程要不要改成「線上＋實體」混合。</p>\n      <table>\n        <tr><th>站</th><th>一句話</th><th>你的判斷</th></tr>\n        <tr><td>1 問題陳述</td><td>要決定的是「不降低分享的混合制」，不是「線上或實體」</td><td>部分同意（負擔 ≤ 1.2 倍）</td></tr>\n        <tr><td>2 SWOT</td><td>線上人數一多，主動分享就掉；遠地需求真實存在</td><td>同意</td></tr>\n        <tr><td>3 加權決策矩陣</td><td>混合制最高分，但「主動分享不降」的權重從 5 改成 3 就翻</td><td>同意</td></tr>\n        <tr><td>總結</td><td>做混合制，條件是每場線上 ≤ 4 人；90 天後看分享人數</td><td>核准</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"partner\" hidden>\n      <p class=\"lead\">合作對象：下一檔展覽要不要續約那家一直延後付款的畫廊。</p>\n      <table>\n        <tr><th>站</th><th>一句話</th><th>你的判斷</th></tr>\n        <tr><td>1 問題陳述</td><td>要決定的是「30 天內收得到款、曝光不掉的展出方式」，不是「續不續約」</td><td>同意</td></tr>\n        <tr><td>2 SWOT</td><td>作品有固定藏家、另一家畫廊邀展；這家近一年四檔都延 30–60 天付款</td><td>同意</td></tr>\n        <tr><td>3 加權決策矩陣</td><td>續約＋逾期條款最高分，但「曝光」的權重從 4 改成 2 就變成自辦展覽</td><td>部分同意（逾期條款要寫進合約才算）</td></tr>\n        <tr><td>總結</td><td>續約一檔，條件是合約寫 30 天付款與逾期條款；這檔結束後看實付日</td><td>核准</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"decision\" hidden>\n      <p class=\"lead\">一個決策：要不要加開平日班。</p>\n      <table>\n        <tr><th>站</th><th>一句話</th><th>你的判斷</th></tr>\n        <tr><td>1 問題陳述</td><td>要決定的是「老師排得出、半年不虧的平日班」，不是「開不開」</td><td>同意</td></tr>\n        <tr><td>2 SWOT</td><td>5 位家長在問、週末班候補 8 人；老師都是兼職，開學後詢問會回落</td><td>同意</td></tr>\n        <tr><td>3 加權決策矩陣</td><td>開一班試半年最高分，但「老師排得出」的權重從 5 改成 3 就變成開兩班</td><td>同意</td></tr>\n        <tr><td>總結</td><td>開一班試半年，條件是老師先排定平日時段；半年後看人數與損益</td><td>核准</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"ecom\" hidden>\n      <p class=\"lead\">電商後台：退貨率 12% 的尺寸類商品要不要改成預購制。</p>\n      <table>\n        <tr><th>站</th><th>一句話</th><th>你的判斷</th></tr>\n        <tr><td>1 問題陳述</td><td>要決定的是「退貨率降到 5% 以下又不拖慢出貨的做法」，不是「預購或不預購」</td><td>同意</td></tr>\n        <tr><td>2 SWOT</td><td>同業改預購後退貨率降到 4%；客服只有 1 人、退貨表不問原因</td><td>同意</td></tr>\n        <tr><td>3 加權決策矩陣</td><td>改預購最高分，但「出貨速度」的權重從 3 改成 5 就變成維持現狀</td><td>部分同意（先補退貨原因欄）</td></tr>\n        <tr><td>總結</td><td>尺寸類改預購，條件是退貨表先加原因欄；三個月後看退貨率</td><td>核准</td></tr>\n      </table>\n    </div>\n    <div class=\"ex\" data-set=\"daily\" hidden>\n      <p class=\"lead\">日常：要不要請家事服務，讓週日晚上不再吵架。</p>\n      <table>\n        <tr><th>站</th><th>一句話</th><th>你的判斷</th></tr>\n        <tr><td>1 問題陳述</td><td>要決定的是「週日晚上不吵、每月不超過 3,000 元的安排」，不是「請不請」</td><td>同意</td></tr>\n        <tr><td>2 SWOT</td><td>兩個人都想解決、社區有按次計費的服務；預算緊、一方不習慣外人進門</td><td>同意</td></tr>\n        <tr><td>3 加權決策矩陣</td><td>每兩週一次最高分，但「費用」的權重從 4 改成 5 就變成不請</td><td>同意</td></tr>\n        <tr><td>總結</td><td>每兩週請一次，條件是先排好分工表；一個月後看週日晚上還吵不吵</td><td>核准</td></tr>\n      </table>\n    </div>\n    </div>\n    <div class=\"btns mt8\"><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">看完整的工作流總覽 →<small><span class=\"ex\" data-set=\"edd\">同一個案例，三站與總結頁</span><span class=\"ex\" data-set=\"partner\" hidden>這個領域的完整總覽還在做</span><span class=\"ex\" data-set=\"decision\" hidden>這個領域的完整總覽還在做</span><span class=\"ex\" data-set=\"ecom\" hidden>這個領域的完整總覽還在做</span><span class=\"ex\" data-set=\"daily\" hidden>這個領域的完整總覽還在做</span></small></button></div>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"walk\">下一個分頁：怎麼走 →</button><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-walk\" role=\"tabpanel\" aria-labelledby=\"tab-walk\" hidden>\n  <div class=\"card\">\n    <h2>怎麼走：兩種走法、每站你要做的、常見錯誤<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先選走法，再看每站的好例壞例。<b>你要做的</b>決定你要一站一站走，還是一次跑完。</div>\n    <div class=\"todos\">\n      <div class=\"todo\"><b>一站一站走</b>每站停下來給你確認，可以改順序、中途換工具。第一次走建議這個。</div>\n      <div class=\"todo\"><b>一次跑完</b>三站自動跑，跑完再逐站看。適合已經走過、只是換資料。</div>\n    </div>\n    <div class=\"gb mt10\">\n      <div class=\"ex\" data-set=\"edd\">\n        <div class=\"good\"><b>好</b>：第 1 站把成功條件寫成看得到的數字（分享人數不降、遠地 ≥ 3 人）。</div>\n        <div class=\"bad\"><b>壞</b>：第 1 站寫「希望變好」。（好在哪？誰看得到？）</div>\n        <div class=\"good\"><b>好</b>：第 3 站的權重自己填，填完看敏感度。</div>\n        <div class=\"bad\"><b>壞</b>：權重讓 AI 填。（那就不是你的決定）</div>\n      </div>\n      <div class=\"ex\" data-set=\"partner\" hidden>\n        <div class=\"good\"><b>好</b>：第 1 站把成功條件寫成看得到的事實（30 天內收款、每檔到場 ≥ 200 人）。</div>\n        <div class=\"bad\"><b>壞</b>：第 1 站寫「合作愉快」。（好在哪？誰看得到？）</div>\n        <div class=\"good\"><b>好</b>：第 3 站的權重自己填（付款準時 5、曝光 4），填完看敏感度。</div>\n        <div class=\"bad\"><b>壞</b>：權重讓 AI 填。（那就不是你的決定）</div>\n      </div>\n      <div class=\"ex\" data-set=\"decision\" hidden>\n        <div class=\"good\"><b>好</b>：第 1 站把成功條件寫成數字（平日班 ≥ 6 人、半年不虧）。</div>\n        <div class=\"bad\"><b>壞</b>：第 1 站寫「有人來就好」。（幾人？多久？誰看得到？）</div>\n        <div class=\"good\"><b>好</b>：第 3 站的權重自己填（老師排得出 5、人數 4），填完看敏感度。</div>\n        <div class=\"bad\"><b>壞</b>：權重讓 AI 填。（那就不是你的決定）</div>\n      </div>\n      <div class=\"ex\" data-set=\"ecom\" hidden>\n        <div class=\"good\"><b>好</b>：第 1 站把成功條件寫成數字（尺寸類退貨率 ≤ 5%、毛利不低於現在）。</div>\n        <div class=\"bad\"><b>壞</b>：第 1 站寫「退貨變少」。（少多少？多久？誰看得到？）</div>\n        <div class=\"good\"><b>好</b>：第 3 站的權重自己填（退貨率 5、出貨速度 3），填完看敏感度。</div>\n        <div class=\"bad\"><b>壞</b>：權重讓 AI 填。（那就不是你的決定）</div>\n      </div>\n      <div class=\"ex\" data-set=\"daily\" hidden>\n        <div class=\"good\"><b>好</b>：第 1 站把成功條件寫成數字（週日晚上零吵架、每月 ≤ NT$3,000）。</div>\n        <div class=\"bad\"><b>壞</b>：第 1 站寫「家裡和平」。（怎麼算和平？誰看得到？）</div>\n        <div class=\"good\"><b>好</b>：第 3 站的權重自己填（不吵 5、費用 4），填完看敏感度。</div>\n        <div class=\"bad\"><b>壞</b>：權重讓 AI 填。（那就不是你的決定）</div>\n      </div>\n    </div>\n    <div class=\"mistake mt8\"><i>✕</i><span><b>跳過第 1 站</b>：直接做 SWOT，最後發現大家在決定不同的事。</span></div>\n    <div class=\"mistake\"><i>✕</i><span><b>退回不重跑</b>：改了第 1 站卻沿用第 3 站的分數；系統會把後面的站標失效，照著重跑就好。</span></div>\n    <div class=\"mistake\"><i>✕</i><span><b>把分數當答案</b>：第 3 站的分數是「按你的權重」算的；先看哪個權重一改就翻，再決定。</span></div>\n    <div class=\"quiz\"><b>自我檢查（30 秒，點開看答案）</b>\n      <details><summary>「權重」在哪一站填、誰填？</summary>第 3 站，你填；AI 只能起草準則候選。</details>\n      <details><summary>改了第 1 站的成功條件，第 3 站要不要重跑？</summary>要；系統會把第 2、3 站標失效並提醒。</details>\n      <div class=\"ex\" data-set=\"edd\"><details><summary>「主動分享不降」的權重從 5 改成 3，結果就從混合制變成全線上：這叫什麼？</summary>敏感度：哪個權重一改結果就翻，那個權重就是你要先想清楚的。</details></div>\n      <div class=\"ex\" data-set=\"partner\" hidden><details><summary>「曝光」的權重從 4 改成 2，結果就從續約變成自辦展覽：這叫什麼？</summary>敏感度：哪個權重一改結果就翻，那個權重就是你要先想清楚的。</details></div>\n      <div class=\"ex\" data-set=\"decision\" hidden><details><summary>「老師排得出」的權重從 5 改成 3，結果就從開一班變成開兩班：這叫什麼？</summary>敏感度：哪個權重一改結果就翻，那個權重就是你要先想清楚的。</details></div>\n      <div class=\"ex\" data-set=\"ecom\" hidden><details><summary>「出貨速度」的權重從 3 改成 5，結果就從改預購變成維持現狀：這叫什麼？</summary>敏感度：哪個權重一改結果就翻，那個權重就是你要先想清楚的。</details></div>\n      <div class=\"ex\" data-set=\"daily\" hidden><details><summary>「費用」的權重從 4 改成 5，結果就從每兩週一次變成不請：這叫什麼？</summary>敏感度：哪個權重一改結果就翻，那個權重就是你要先想清楚的。</details></div>\n    </div>\n  </div>\n\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn\" data-tab-go=\"read\">下一個分頁：看懂總覽 →</button><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-read\" role=\"tabpanel\" aria-labelledby=\"tab-read\" hidden>\n  <div class=\"card\">\n    <h2>看懂總覽：走這條路時那一頁怎麼讀<small>30 秒</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>先看三步讀法，再對照下面每一塊；總覽頁每塊開頭只留一句，詳細讀法都在這裡。<b>你要做的</b>不用做；總覽頁哪一塊看不懂，回這個分頁找同一個名字。</div>\n    <div class=\"todos\">\n      <div class=\"todo\"><b>① 先看站列</b>你在第幾站、哪些已完成、下一站是什麼。</div>\n      <div class=\"todo\"><b>② 看現在這一站的格子</b>它回答什麼、從上一站帶入什麼（已經填好）、還要你填哪幾格；填好按「執行這一站」。</div>\n      <div class=\"todo\"><b>③ 看摘要與總結頁骨架</b>已完成的站只留一句話和你的判斷；跑完第 3 站才有總結頁。</div>\n    </div>\n    <p class=\"sub mt8\">只有 30 秒？看站列和現在這一站要你填的格子就夠。</p>\n    <div class=\"terms\"><b>四個詞：</b><span><b>站</b> 一個工具一站</span><span><b>帶入</b> 上一站的結果自動變成這站的輸入</span><span><b>還要你填</b> 系統填不了的格子</span><span><b>總結頁</b> 三站合一的結論</span></div>\n    <h3 class=\"fam\">總覽頁每一塊回答一件事</h3>\n    <div class=\"row\"><b>頁首</b><span>狀態列說草稿還是已核准、走到第幾站、資料有多少、全程大約多少錢（已用多少）；右上角「怎麼用？」開這堂課。兩種走法：一站一站走（每站停下來給你確認，第一次走選這個）、一次跑完（跑完再逐站看）。</span></div>\n    <div class=\"row\"><b>站卡</b><span>每站一張：回答什麼、從上一站帶入什麼、還要你填幾格（紅字）、會得到什麼、大約多久多少錢；第一次到站會跳出那一站工具的課，可跳。</span></div>\n    <div class=\"row\"><b>現在這一站</b><span>「脈絡」是上一站帶入的，不用填；下面的格子你填，可以先按「用示範案例填入」看看長什麼樣。按「執行這一站」才花錢。</span></div>\n    <div class=\"row\"><b>已完成站的摘要</b><span>只放一句話結論和你的判斷；完整九段在那一站自己的結果頁。覺得問題定錯了，回去改，後面的站會標失效、重跑時前面的不用重填。</span></div>\n    <div class=\"row\"><b>總結頁</b><span>跑完最後一站才出現：三站合一的一句話、每站一句＋你的判斷＋信心、最終建議與改判條件、解決方案、跨站引註、成本合計。</span></div>\n    <div class=\"row\"><b>引註與核准</b><span>[n] 從第 1 站往後編號，不重排；「上一站帶入」的內容標它來自哪一站的哪一欄。最下面：核准整條、退回某一站（之後的站失效）、專家模式收著每站的閘門表與 JSON。</span></div>\n  </div>\n  <div class=\"tabnext\"><button type=\"button\" class=\"btn primary\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">開始我的決定 →</button><button type=\"button\" class=\"btn\" data-note=\"一站一站走的工作流頁面還在做：現在可以先從站列裡的工具單獨開始。\">對照走到一半的示範 →</button></div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-teach\" role=\"tabpanel\" aria-labelledby=\"tab-teach\" hidden>\n  <div class=\"card\">\n    <h2>教材版：給老師／帶領者<small>同一份資料，另一種排版</small></h2>\n    <div class=\"how\"><b>怎麼讀</b>其他分頁是學員版（3 分鐘自學）；這裡把同一條路排成 45 分鐘課堂：流程、講稿要點、討論題、學員常錯、講義。每一站的深度用該站工具的教材版，這裡只排「怎麼把三站走一遍」。<b>你要做的</b>只在你要教別人時展開；可整份匯出成講義與投影片大綱。</div>\n    <details><summary><b>課堂流程（45 分鐘）</b></summary>\n      <table class=\"mt6\">\n        <tr><th>分</th><th>做什麼</th><th>用學員版哪一頁</th></tr>\n        <tr><td>0–5</td><td>破冰：每人說一個還沒做、「幾個選項選一個」的決定</td><td>「認識」的「能／不能回答」</td></tr>\n        <tr><td>5–15</td><td>講三站各做什麼，例子換成學員的領域；每站只講「要你填的那一列」</td><td>「各站」（切領域）</td></tr>\n        <tr><td>15–30</td><td>分組把自己的決定走一遍：第 1 站三格、第 2 站四格各兩條、第 3 站自己定權重</td><td>「各站」的填好例子</td></tr>\n        <tr><td>30–40</td><td>各組報告哪個權重一改結果就翻；其他組專門找「跳過第 1 站」和「權重全 5」</td><td>「怎麼走」</td></tr>\n        <tr><td>40–45</td><td>收尾：改了第 1 站就要重跑後面；帶大家看一次總覽頁；預告每站的工具課</td><td>「開始」卡、「看懂總覽」、總覽頁</td></tr>\n      </table>\n    </details>\n    <details><summary><b>講稿要點（每步 2–3 句）</b></summary>\n      <ul class=\"check\">\n        <li>這條路解什麼：先問「你們最近有沒有一件事大家意見不一、選項超過一個」，再給站列。不要先講工具名。</li>\n        <li>三站：用「定問題／看自己和外面／用你的權重打分」三個詞帶，每站停 30 秒讓學員對到自己的決定。</li>\n        <li>走完的例子：只講「每站一句、最後一句三站合一」，不要解釋案例細節。</li>\n        <li>怎麼走：把「權重全 5」的壞例投影出來，讓學員說為什麼沒意義。</li>\n        <li>開始：告訴學員第一次走選「一站一站走」，每站都會停下來確認。</li>\n      </ul>\n    </details>\n    <details><summary><b>討論題（3 題）</b></summary>\n      <ol class=\"src\">\n        <li>你的決定裡，哪個成功條件最難寫成數字？為什麼？</li>\n        <li>如果權重全部由別人定，這還算你的決定嗎？</li>\n        <li>哪個權重一改結果就翻？你願意為它去補什麼資料？</li>\n      </ol>\n    </details>\n    <details><summary><b>學員最常錯的三件事，怎麼接</b></summary>\n      <ul class=\"check\">\n        <li>成功條件寫成「希望變好」 → 反問：「三個月後，你怎麼知道成了？」要一個看得到的數字或事實。</li>\n        <li>機會與威脅寫成心情 → 反問：「這件事現在存在嗎？別人也看得到嗎？」是事實才進 O／T。</li>\n        <li>權重全填 5 → 反問：「如果只能保住一個條件，你保哪個？」那個才是 5。</li>\n      </ul>\n    </details>\n    <details><summary><b>講義與投影片</b></summary>\n      <p class=\"my6\">列印版講義 = 第 2 步三站的「你要填」列與填好的例子（學員領域版）＋一張空白三站工作單；投影片大綱 = 五步各一頁＋站列一頁。兩者都從這一頁匯出（匯出功能還在做）。</p>\n    </details>\n    <p class=\"sub mt8 mb0\">教材版和學員版由同一份工作流資料生成（來源 [1]–[2]），改課文就同時改兩版。每一站的工具深度在該站工具課的教材版，這裡不重寫。</p>\n  </div>\n  </section>\n\n  <section class=\"tabpanel\" id=\"panel-sources\" role=\"tabpanel\" aria-labelledby=\"tab-sources\" hidden>\n  <div class=\"card\">\n    <h2>課程來源（每段課文的 [n]）</h2>\n    <div class=\"how\"><b>怎麼讀</b>[n] 是那段課文的依據；工作流的課引用它自己的定義檔和三站工具的課。<b>你要做的</b>不用做；發現寫錯可以回報。</div>\n    <ol class=\"src\">\n      <li>工作流定義 `life-decision-v1.recipe.yaml`（三站順序與站間帶入的欄位）</li>\n      <li>三站工具各自的 5 分鐘課（問題陳述、SWOT、加權決策矩陣；各有自己的來源）</li>\n    </ol>\n  </div>\n  </section>\n" },
};
